PAGES.push('favorites');let favoriteFilter='all',favoriteQuery='',favoriteRecall=false;
function favoriteRecord(key){const [kind,id,index]=key.split(':');if(kind==='word'){const w=words.find(w=>w.id===id);return w?{key,kind,level:w.level,title:w.word,reading:w.reading,meaning:w.meaning+' · '+w.pos,speak:w.reading}:null;}const g=grammar.find(g=>g.id===id);if(!g)return null;if(kind==='example'){const e=g.examples[Number(index)];return e?{key,kind,level:g.level,title:e[0],reading:'',meaning:e[1],speak:e[0],lesson:id}:null;}return {key,kind,level:g.level,title:g.title,reading:'',meaning:g.rule,speak:g.examples[0]?.[0]||'',lesson:id};}
function favoriteButton(k){return n4Favorite(k);}
function renderFavorites(){const all=state.favorites.map(favoriteRecord).filter(Boolean),items=all.filter(x=>(favoriteFilter==='all'||x.kind===favoriteFilter)&&[x.title,x.meaning,x.level].join(' ').includes(favoriteQuery.trim()));return title('','收藏与复习','')+`<section class="container page-section"><div class="toolbar">${[['all','全部'],['word','单词'],['grammar','句型'],['example','例句']].map(([k,n])=>`<button class="chip ${favoriteFilter===k?'selected':''}" data-fav-filter="${k}">${n} ${k==='all'?all.length:all.filter(x=>x.kind===k).length}</button>`).join('')}<button class="secondary" id="favoriteRecall" aria-pressed="${favoriteRecall}">${favoriteRecall?'返回浏览':'回忆模式：先想再展开'}</button></div><label>搜索收藏<input id="favoriteSearch" type="search" value="${esc(favoriteQuery)}" placeholder="日文、中文或等级"></label><div id="favoriteList">${favoriteCards(items)}</div></section>`;}
function favoriteCards(items){return items.length?`<div class="favorite-grid">${items.map(x=>`<article class="favorite-card"><span class="label">${x.level} · ${{word:'单词',grammar:'句型',example:'例句'}[x.kind]}</span><h3 lang="ja">${esc(x.title)}</h3><details ${!favoriteRecall?'open':''}><summary>${favoriteRecall?'回忆后查看答案':'读音与释义'}</summary>${x.reading?`<p>${esc(x.reading)}</p>${romanLine(x.reading)}`:''}<p>${esc(x.meaning)}</p></details><div class="toolbar"><button class="secondary" data-speak="${esc(x.speak)}">▷ 跟读</button>${x.lesson?`<button class="secondary" data-lesson="${x.lesson}">查看讲解</button>`:''}${favoriteButton(x.key)}</div></article>`).join('')}</div>`:'<div class="empty-state">没有匹配的收藏。在单词、句型或例句旁点击「☆ 收藏」，即可集中复习。</div>';}
const favoriteOriginalOpen=openLesson;openLesson=function(id){favoriteOriginalOpen(id);const g=grammar.find(g=>g.id===id);if(!g)return;$('#lessonBody').innerHTML+=`<div class="favorite-lesson-actions">${favoriteButton('grammar:'+id)}${g.examples.map((e,i)=>`<div><p lang="ja">${esc(e[0])}</p>${favoriteButton('example:'+id+':'+i)}</div>`).join('')}</div>`;};
const favoriteOriginalWords=n5WordStage;n5WordStage=function(u){let html=favoriteOriginalWords(u);for(const id of u.wordIds)html=html.replace(`data-word-id="${id}">`,`data-word-id="${id}">${favoriteButton('word:'+id)}`);return html;};
const favoriteOriginalGrammar=n5GrammarStage;n5GrammarStage=function(u){let html=favoriteOriginalGrammar(u);u.grammar.forEach((g,i)=>{const id=u.grammarIds[i];html=html.replace(`<h2>${esc(g.title)}</h2>`,`<h2>${esc(g.title)}</h2>${favoriteButton('grammar:'+id)}`);g.examples.forEach((e,j)=>{html=html.replace(`<b lang="ja">${esc(e[0])}</b>`,`<b lang="ja">${esc(e[0])}</b>${favoriteButton('example:'+id+':'+j)}`);});});return html;};
const favoriteOriginalCard=wordCard;wordCard=function(){const html=favoriteOriginalCard(),w=visibleWords()[wordCursor];return html+(w?`<div class="favorite-card-action">${favoriteButton('word:'+w.id)}</div>`:'');};
const favoritePreviousRender=render;render=function(scroll=true){if(page!=='favorites')return favoritePreviousRender(scroll);$('#view').innerHTML=renderFavorites();$('#levelTabs').innerHTML=LEVELS.map(l=>`<button data-level="${l}" class="${l===level?'selected':''}">${l}</button>`).join('');document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page==='favorites'));if(scroll)window.scrollTo({top:0,behavior:'instant'});};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.favorite){if(!favoriteRecord(d.favorite))return;state.favorites=state.favorites.includes(d.favorite)?state.favorites.filter(k=>k!==d.favorite):[...state.favorites,d.favorite];persist();document.querySelectorAll('[data-favorite]').forEach(btn=>{if(btn.dataset.favorite===d.favorite){const on=state.favorites.includes(d.favorite);btn.textContent=on?'★ 已收藏':'☆ 收藏';btn.setAttribute('aria-pressed',String(on));}});if(page==='favorites')render(false);toast(state.favorites.includes(d.favorite)?'已加入收藏，可集中复习。':'已取消收藏。');}if(d.favFilter){favoriteFilter=d.favFilter;render(false);}if(b.id==='favoriteRecall'){favoriteRecall=!favoriteRecall;render(false);}});
document.addEventListener('input',e=>{if(e.target.id==='favoriteSearch'){favoriteQuery=e.target.value;const items=state.favorites.map(favoriteRecord).filter(Boolean).filter(x=>(favoriteFilter==='all'||x.kind===favoriteFilter)&&[x.title,x.meaning,x.level].join(' ').includes(favoriteQuery.trim()));$('#favoriteList').innerHTML=favoriteCards(items);}});
fromHash();
